// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge as C} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzz the player address (actor) so fuzzer finds an address that can trigger the mutant
    function testFuzz_property(address actor) public {
        actor = address(uint160(bound(uint256(uint160(actor)), 0xffff + 1, type(uint160).max)));
        vm.assume(actor.code.length == 0 && actor != address(this) && actor != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && actor != 0x000000000000000000636F6e736F6c652e6c6f67 && actor != 0x4e59b44847b379578588920cA78FbF26c0B4956C && actor != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(actor != address(0));
        // prepare actor with 1 ether to lock a guess
        vm.deal(actor, 1 ether);

        // actor calls lockInGuess in the same block we'll try to call settle
        bytes32 dummy = keccak256(abi.encodePacked("guess"));
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(dummy);

        // Now attempt to call settle immediately in the same block.
        // On the reference contract this must NOT allow a successful payout (settle should require block.number > recorded)
        // We call settle and record whether it succeeded (did not revert).
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: for the correct contract, immediate settle (same block) must never succeed for any actor.
        // This assertTrue reads c via its behavior (settle success boolean) and will PASS on the reference for all inputs,
        // while the mutant that allows block.number >= recorded can allow ok == true for some actor (fuzzer will find one).
        assertTrue(!ok);
    }
}
